import json
def c(t,u,r): return dict(title=t,url=u,relation=r)
OCTAG=c("Anomaly guided weakly supervised lesion segmentation on retinal OCT","https://researchconnect.stonybrook.edu/en/publications/anomaly-guided-weakly-supervised-lesion-segmentation-on-retinal-o/","uses anomaly-detection evidence to guide weakly supervised lesion segmentation in OCT, the general idea of letting a weakly supervised signal steer segmentation")
WSSS=c("Emerging Trends in Pseudo-Label Refinement for Weakly Supervised Semantic Segmentation with Image-Level Supervision (arXiv 2507.21587)","https://arxiv.org/pdf/2507.21587","surveys pseudo-label refinement from image-level labels, including teacher-student and cross-view filtering")
LIVER=c("Anatomical prior-inspired label refinement for weakly supervised liver tumor segmentation with volume-level labels (BMVC 2022)","https://bmvc2022.mpi-inf.mpg.de/1054","refines pseudo-labels for liver tumours from coarse labels, a medical precedent for iterative label refinement")
COIN=c("COIN: Counterfactual inpainting for weakly supervised semantic segmentation for medical images (arXiv 2404.12832)","https://arxiv.org/html/2404.12832v2","derives segmentation masks from the change in a classifier's output under counterfactual inpainting, close to occlusion attribution and normal-twin differencing")
