SELF=c("A Closer Look at Self-training for Zero-Label Semantic Segmentation (arXiv 2104.11692)","https://arxiv.org/pdf/2104.11692","self-training with regenerated pseudo-labels for unseen classes, the general mechanism of iterative pseudo-label regeneration")
CLIPT=c("CLIP Is Also a Good Teacher: inductive zero-shot semantic segmentation (arXiv 2310.02296)","https://arxiv.org/pdf/2310.02296","uses CLIP as a teacher for segmentation pseudo-labels")
