TILED=c("Divide and Conquer: High-Resolution Industrial Anomaly Detection via Memory Efficient Tiled Ensemble (arXiv 2403.04932)","https://arxiv.org/html/2403.04932v1","ensembles over tiles to raise anomaly-map resolution")
REGAD=c("Registration Based Few-Shot Anomaly Detection (ECCV 2022)","https://www.ecva.net/papers/eccv_2022/papers_ECCV/html/1729_ECCV_2022_paper.php","compares registered query and support features for few-shot anomaly detection, close to normal-twin differencing")
AFF=c("Learning Pixel-level Semantic Affinity with Image-level Supervision (AffinityNet, arXiv 1803.10464)","https://arxiv.org/pdf/1803.10464","refines class-activation pseudo-labels with learned pixel affinities; edge-aware refinement of coarse maps is established")
HIFI=c("High-fidelity Pseudo-labels for Boosting Weakly-Supervised Segmentation (arXiv 2304.02621)","https://ar5iv.labs.arxiv.org/html/2304.02621","refines coarse pseudo-labels with image-guided upsampling")
