LOOC=c("Leave-One-Out-, Bootstrap- and Cross-Conformal Anomaly Detectors (arXiv 2402.16388)","https://arxiv.org/pdf/2402.16388","develops leave-one-out conformal p-values for anomaly detectors, the core of support-LOO conformal scoring")
WCAD=c("Between Resolution Collapse and Variance Inflation: Weighted Conformal Anomaly Detection in Low-Data Regimes (arXiv 2603.23205)","https://arxiv.org/pdf/2603.23205","studies weighted conformal anomaly detection when calibration sets are small, very close to borrowing weighted source normals")
CAL=c("Enabling Calibration In The Zero-Shot Inference of Large Vision-Language Models (ICLR 2023 workshop, arXiv 2303.12748)","https://arxiv.org/pdf/2303.12748","fits a temperature for CLIP zero-shot predictions that transfers across datasets; supports temperature calibration of MVFA's zero-shot branch")
FREE=c("Free Lunch for Few-shot Learning: Distribution Calibration (arXiv 2101.06395)","https://arxiv.org/pdf/2101.06395","calibrates few-shot class statistics by borrowing from base-class statistics, the few-shot analogue of empirical-Bayes shrinkage")
